    bosses: [
      { name: 'Houndmaster Loksey', npc: 3974, model: 2040, spells: [4304, 11549, 6742], loot: [3456, 7756, 7710], strategy: 'Three elite hounds come with him. Crowd-control one (beast CC works), tank Loksey while DPS kill the hounds, then him. He Bloodlusts at low health.', tank: 'Hold Loksey while the hounds die.', healer: 'Watch for the Bloodlust.', dps: 'Hounds first.' },
      { name: 'Arcanist Doan', npc: 6487, model: 5266, spells: [9438, 9433, 9435, 13323, 8988], loot: [7712, 7711, 7713, 7714], strategy: 'Tank him in the middle with ranged spread toward the edges. When he starts Detonation, run to the edge of the room, or use the pillars in the previous hall to break line of sight. He also polymorphs and casts Arcane Explosion.', tank: 'Run out for Detonation too.', healer: 'Group damage from Arcane Explosion.', dps: 'Run to the edges for Detonation.' },
    ],
